                if (Session["image_url"] != null)
                    imguser.ImageUrl = System.Configuration.ConfigurationManager.AppSettings["ImageNDocService"].ToString() + "1" + "&filename=" + Convert.ToString(Session["image_url"]);
                else
                    imguser.ImageUrl = "~/style/images/blankimage.JPG";
